/// Ошибка хода
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct ChatHistoryError {
    /// Причина:
    /// - `budget` — кончился лимит (дня или разговора)
    /// - `parallel_turns_limit` — у человека уже идёт предельное число ходов ИИ (тариф без доп. использования) — дождаться ответа на предыдущие вопросы
    /// - `rate_limited` — сервис модели перегружен — повторите
    /// - `api` — сбой сервиса модели
    /// - `refusal` — модель отказалась отвечать
    /// - `context_overflow` — разговор слишком длинный — начните новый
    /// - `aborted` — ход остановили
    /// - `max_iterations` — ИИ не уложился в предел шагов — попросите по частям
    /// - `max_tokens` — ответ слишком длинный и оборвался — попросите короче или по частям
    /// - `empty_answer` — модель закончила ход без ответа — повторите вопрос
    /// - `unexpected` — ход закончился неожиданно — повторите вопрос
    /// - `history` — ответ не сохранился в истории
    /// - `internal` — внутренняя ошибка
    /// - `stream_failed` — поток ответа оборвался на нашей стороне
    /// - `batch_failed` — пачка прервана ошибкой
    /// - `batch_abandoned` — пачка брошена (процесс перезапущен)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub code: Option<ChatHistoryErrorCode>,
    /// Ошибка хода
    pub kind: String,
    /// Текст для человека
    pub message: String,
}

impl Default for ChatHistoryError {
    fn default() -> Self {
        Self {
            code: None,
            kind: "error".to_owned(),
            message: Default::default(),
        }
    }
}

string_enum! {
    /// Причина:
    /// - `budget` — кончился лимит (дня или разговора)
    /// - `parallel_turns_limit` — у человека уже идёт предельное число ходов ИИ (тариф без доп. использования) — дождаться ответа на предыдущие вопросы
    /// - `rate_limited` — сервис модели перегружен — повторите
    /// - `api` — сбой сервиса модели
    /// - `refusal` — модель отказалась отвечать
    /// - `context_overflow` — разговор слишком длинный — начните новый
    /// - `aborted` — ход остановили
    /// - `max_iterations` — ИИ не уложился в предел шагов — попросите по частям
    /// - `max_tokens` — ответ слишком длинный и оборвался — попросите короче или по частям
    /// - `empty_answer` — модель закончила ход без ответа — повторите вопрос
    /// - `unexpected` — ход закончился неожиданно — повторите вопрос
    /// - `history` — ответ не сохранился в истории
    /// - `internal` — внутренняя ошибка
    /// - `stream_failed` — поток ответа оборвался на нашей стороне
    /// - `batch_failed` — пачка прервана ошибкой
    /// - `batch_abandoned` — пачка брошена (процесс перезапущен)
    ChatHistoryErrorCode {
        Budget = "budget",
        ParallelTurnsLimit = "parallel_turns_limit",
        RateLimited = "rate_limited",
        Api = "api",
        Refusal = "refusal",
        ContextOverflow = "context_overflow",
        Aborted = "aborted",
        MaxIterations = "max_iterations",
        MaxTokens = "max_tokens",
        EmptyAnswer = "empty_answer",
        Unexpected = "unexpected",
        History = "history",
        Internal = "internal",
        StreamFailed = "stream_failed",
        BatchFailed = "batch_failed",
        BatchAbandoned = "batch_abandoned",
    }
}

