/// Тело любой ошибки API (статусы 4xx и 5xx): `{"type":"error","error":{"type":"…","code":"…","message":"…"},"request_id":"…"}`. Интерфейс ветвится по error.type и error.code, человеку показывает error.message и request_id.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(default)]
#[non_exhaustive]
pub struct Error {
    pub error: ErrorDetail,
    /// Номер запроса (тот же, что в заголовке x-request-id). Показывать мелко рядом с ошибкой с кнопкой «скопировать»: по нему поддержка находит запрос в журнале. null — номер не успел появиться (очень ранний отказ).
    pub request_id: Option<String>,
    /// Всегда «error»: так тело ошибки отличается от обычного ответа.
    #[serde(rename = "type")]
    pub type_: String,
}

impl Default for Error {
    fn default() -> Self {
        Self {
            error: Default::default(),
            request_id: Default::default(),
            type_: "error".to_owned(),
        }
    }
}

